using System.Net.Http.Headers; using System.Net.Http.Json; using System.Text.Json; using PlantaoPro.Web.Models;
namespace PlantaoPro.Web.Services;
public sealed class FechamentoWebService(IHttpClientFactory factory)
{
 private static readonly JsonSerializerOptions Options=new(){PropertyNameCaseInsensitive=true};
 public async Task<FechamentoViewModel> GetAsync(string token,bool pending,Guid? id,CancellationToken ct){var client=factory.CreateClient("PlantaoProApi");client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token);var path=id.HasValue?$"api/fechamentos/{id}":pending?"api/fechamentos/pendentes":"api/fechamentos";using var response=await client.GetAsync(path,ct);if(!response.IsSuccessStatusCode)return new([],[],[]);using var doc=JsonDocument.Parse(await response.Content.ReadAsStringAsync(ct));var data=doc.RootElement.GetProperty("data");var rows=data.ValueKind==JsonValueKind.Array?data.EnumerateArray().ToArray():new[]{data};var items=rows.Select(x=>new OperationalWorkItemViewModel(x.GetProperty("id").GetString()!, $"Plantão {x.GetProperty("plantaoId").GetString()![..8]}", $"{x.GetProperty("hospital").GetString()} · {x.GetProperty("especialidade").GetString()}",x.GetProperty("status").GetString()!,x.GetProperty("divergenciasAbertas").GetInt32()>0?"Alta":"Normal","Operação",Next(x.GetProperty("status").GetString()!),$"/fechamentos/{x.GetProperty("id").GetString()}")).ToArray();var value=rows.Sum(x=>x.GetProperty("valorApurado").GetDecimal());var open=rows.Sum(x=>x.GetProperty("divergenciasAbertas").GetInt32());return new([new("Fechamentos",rows.Length.ToString(),"Registros persistidos","primary"),new("Valor apurado",value.ToString("C"),"Snapshot financeiro real","success"),new("Divergências",open.ToString(),"Abertas","warning")],items,[]);}
 private static string Next(string status)=>status switch{"ABERTO"=>"Iniciar conferência","EM_CONFERENCIA"=>"Concluir conferência","COM_DIVERGENCIA"=>"Resolver divergências","AGUARDANDO_APROVACAO"=>"Aprovar ou devolver","APROVADO"=>"Gerar financeiro",_=>"Consultar"};
}
